<?php
if(!defined('ABSPATH'))exit; final class DSVS_Fetcher{public static function get($u,$ttl,$ns){$k='dsvs_'.sanitize_key($ns).'_'.md5($u);$c=get_transient($k);if($c!==false)return $c;$r=wp_safe_remote_get($u,array('timeout'=>12,'redirection'=>3,'limit_response_size'=>1048576));if(is_wp_error($r))return $r;$b=wp_remote_retrieve_body($r);if(wp_remote_retrieve_response_code($r)!==200||strlen($b)<500||stripos($b,'<table')===false)return new WP_Error('source','Ungültige DSVS-Antwort');set_transient($k,$b,$ttl);return $b;}}
